css:
.quiet-page { --quiet-text: #555a5e; --quiet-strong: #3f4448; --quiet-muted: #94999d; --quiet-line: #dde0e2; --quiet-soft: #f7f8f8; min-height: 100%; padding: 56px 28px; background: #ffffff; color: var(--quiet-text); font-family: Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif; font-size: 13px; line-height: 1.7; letter-spacing: -0.01em; }
.quiet-page *, .quiet-page *::before, .quiet-page *::after { box-sizing: border-box; }
.quiet-frame { width: min(920px, 100%); margin: 0 auto; border: 1px solid var(--quiet-line); background: #ffffff; }
.quiet-topbar { min-height: 44px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 18px; border-bottom: 1px solid var(--quiet-line); }
.quiet-brand { min-width: 0; color: var(--quiet-strong); font-size: 13px; font-weight: 600; letter-spacing: 0.01em; text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.quiet-topmark { flex: 0 0 auto; color: var(--quiet-muted); font-size: 9px; letter-spacing: 0.16em; }
.quiet-layout { display: grid; grid-template-columns: 210px minmax(0, 1fr); min-height: 520px; }
.quiet-sidebar { padding: 28px 22px 34px; border-right: 1px solid var(--quiet-line); }
.quiet-profile { padding-bottom: 24px; border-bottom: 1px solid var(--quiet-line); }
.quiet-avatar { display: block; width: 62px; height: 62px; margin: 0 0 14px; border: 1px solid var(--quiet-line); border-radius: 0; background: var(--quiet-soft); object-fit: cover; }
.quiet-avatar:not([src]) { color: transparent; }
.quiet-name { margin: 0 0 5px; color: var(--quiet-strong); font-size: 12px; font-weight: 600; }
.quiet-bio { margin: 0; color: var(--quiet-muted); font-size: 11px; line-height: 1.65; word-break: keep-all; overflow-wrap: anywhere; }
.quiet-nav { padding-top: 22px; }
.quiet-home { display: block; margin: 0 0 22px; color: var(--quiet-strong); font-size: 10px; font-weight: 600; letter-spacing: 0.12em; text-decoration: none; }
.quiet-nav-group + .quiet-nav-group { margin-top: 20px; }
.quiet-label { margin: 0 0 7px; color: var(--quiet-muted); font-size: 9px; letter-spacing: 0.16em; }
.quiet-link-list { list-style: none; margin: 0; padding: 0; }
.quiet-link-list li { border-top: 1px solid var(--quiet-line); }
.quiet-link-list li:last-child { border-bottom: 1px solid var(--quiet-line); }
.quiet-link-list a { display: block; padding: 7px 2px; color: var(--quiet-text); font-size: 11px; text-decoration: none; overflow-wrap: anywhere; }
.quiet-home:hover, .quiet-link-list a:hover, .quiet-brand:hover, .quiet-back:hover, .quiet-post-nav a:hover { color: var(--quiet-strong); text-decoration: underline; text-underline-offset: 3px; }
.quiet-main { min-width: 0; padding: 38px 42px 50px; }
.quiet-section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; min-height: 34px; padding-bottom: 12px; border-bottom: 1px solid var(--quiet-strong); }
.quiet-eyebrow { margin: 0; color: var(--quiet-strong); font-size: 10px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; }
.quiet-count-note, .quiet-back { margin: 0; color: var(--quiet-muted); font-size: 9px; letter-spacing: 0.1em; text-decoration: none; }
.quiet-post-list { list-style: none; margin: 0; padding: 0; }
.quiet-post-item { border-bottom: 1px solid var(--quiet-line); }
.quiet-post-link { display: grid; grid-template-columns: 76px minmax(0, 1fr) auto 150px; align-items: baseline; gap: 12px; min-height: 48px; padding: 14px 2px 12px; color: var(--quiet-text); text-decoration: none; }
.quiet-category-link { grid-template-columns: minmax(0, 1fr) auto 150px; }
.quiet-post-category { color: var(--quiet-muted); font-size: 10px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.quiet-post-title { min-width: 0; color: var(--quiet-strong); font-size: 12px; font-weight: 500; overflow-wrap: anywhere; }
.quiet-post-link:hover .quiet-post-title { text-decoration: underline; text-underline-offset: 4px; }
.quiet-lock { padding: 1px 5px; border: 1px solid var(--quiet-line); color: var(--quiet-muted); font-size: 8px; line-height: 1.4; letter-spacing: 0.08em; }
.quiet-date { color: var(--quiet-muted); font-size: 9px; line-height: 1.5; text-align: right; overflow-wrap: anywhere; }
.quiet-post-list:empty::after { content: '아직 작성된 글이 없습니다.'; display: block; padding: 32px 2px; color: var(--quiet-muted); font-size: 11px; }
.quiet-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 38px; padding: 0 18px; border-top: 1px solid var(--quiet-line); color: var(--quiet-muted); font-size: 8px; letter-spacing: 0.13em; text-transform: uppercase; }
.quiet-post-main { padding-top: 34px; }
.quiet-post-nav { margin: 0 0 18px; }
.quiet-post-nav a { color: var(--quiet-muted); font-size: 10px; text-decoration: none; }
.quiet-post-nav a::before { content: 'CATEGORY / '; color: var(--quiet-muted); letter-spacing: 0.08em; }
.quiet-article-head { padding-bottom: 22px; border-bottom: 1px solid var(--quiet-strong); }
.quiet-article-title { margin: 0 0 9px; color: var(--quiet-strong); font-size: 18px; font-weight: 600; line-height: 1.5; letter-spacing: -0.02em; word-break: keep-all; overflow-wrap: anywhere; }
.quiet-article-date { margin: 0; color: var(--quiet-muted); font-size: 9px; overflow-wrap: anywhere; }
.quiet-post-body { max-width: 100%; padding-top: 28px; color: var(--quiet-text); font-size: 13px; line-height: 1.9; overflow-wrap: anywhere; }
.quiet-post-body img { max-width: 100%; height: auto; }
.quiet-page [hidden] { display: none; }
@media (max-width: 720px) { .quiet-page { padding: 18px 14px 28px; font-size: 13px; } .quiet-topbar { min-height: 42px; padding: 0 14px; } .quiet-topmark { font-size: 8px; } .quiet-layout { display: block; min-height: 0; } .quiet-sidebar { padding: 20px 16px 18px; border-right: 0; border-bottom: 1px solid var(--quiet-line); } .quiet-profile { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 12px; align-items: start; padding-bottom: 16px; } .quiet-avatar { width: 52px; height: 52px; margin: 0; } .quiet-profile-copy { min-width: 0; } .quiet-nav { padding-top: 15px; } .quiet-home { margin-bottom: 13px; } .quiet-nav-group { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 8px; align-items: start; } .quiet-nav-group + .quiet-nav-group { margin-top: 10px; } .quiet-label { padding-top: 7px; } .quiet-link-list { display: flex; flex-wrap: wrap; gap: 0 14px; } .quiet-link-list li, .quiet-link-list li:last-child { border: 0; } .quiet-link-list a { padding: 5px 0; text-decoration: underline; text-decoration-color: var(--quiet-line); text-underline-offset: 3px; } .quiet-main { padding: 27px 16px 38px; } .quiet-section-head { min-height: 31px; padding-bottom: 10px; } .quiet-post-link, .quiet-category-link { grid-template-columns: minmax(0, 1fr) auto; gap: 5px 9px; padding: 13px 1px; } .quiet-post-category { grid-column: 1; grid-row: 1; white-space: normal; } .quiet-post-title { grid-column: 1; grid-row: 2; font-size: 12px; } .quiet-lock { grid-column: 2; grid-row: 2; } .quiet-date { grid-column: 1 / -1; grid-row: 3; text-align: left; } .quiet-category-link .quiet-post-title { grid-row: 1; } .quiet-category-link .quiet-lock { grid-row: 1; } .quiet-category-link .quiet-date { grid-row: 2; } .quiet-footer { padding: 0 14px; } .quiet-post-main { padding-top: 25px; } .quiet-article-head { padding-bottom: 18px; } .quiet-article-title { font-size: 16px; line-height: 1.55; } .quiet-post-body { padding-top: 22px; font-size: 13px; line-height: 1.85; } }
